#!/usr/bin/env python3
import sqlite3,collections,csv,pathlib,json,hashlib
from matplotlib import pyplot as plt
r=pathlib.Path(__file__).resolve().parent.parent;db=sqlite3.connect(r/'data'/'AFTERLIFE_STAGE17_CANONICAL.sqlite');q=collections.defaultdict(collections.Counter)
for date,status in db.execute('SELECT issuance_date,combined_legacy_provisional_status FROM reconciled_legacy_checkpoint2_provisional'):
 try:year=int(str(date)[:4])
 except:year=0
 decade=year//10*10 if year else 0;q[decade][status]+=1
with (r/'reports'/'DECADE_WORKING_CENSUS.csv').open('w',newline='') as f:
 w=csv.writer(f);w.writerow(['issuance_decade','included_proxy_count','legacy_yes','legacy_no','legacy_unknown','stage17_scoped_provisional_first_end','human_certified'])
 for dec in list(range(1780,2030,10))+[0]:
  c=q[dec];n=sum(c.values());q1=db.execute('SELECT count(*) FROM stage17_transition t JOIN stage17_provision p ON p.provision_id=t.affected_provision_id JOIN instruments i ON i.id=p.instrument_id WHERE first_cause_inference=? AND CAST(substr(i.issuance_date,1,4) AS INT) BETWEEN ? AND ?',('FIRST_NORMATIVE_SUNSET',dec,dec+9)).fetchone()[0]
  w.writerow([str(dec) if dec else 'undated',n,c['yes'],c['no'],c['indeterminate'],q1,0])
fig,ax=plt.subplots(figsize=(16.5,6.6)); years=list(range(1790,2030,10)); ys=[y for y in years];no=[q[y]['no'] for y in ys];yes=[q[y]['yes'] for y in ys];un=[q[y]['indeterminate'] for y in ys]
ax.bar(ys,no,width=8.4,color='#607e99',label='Provisional NO');ax.bar(ys,yes,bottom=no,width=8.4,color='#3a9f78',label='Provisional YES');ax.bar(ys,un,bottom=[a+b for a,b in zip(no,yes)],width=8.4,color='#c9d0d7',label='UNKNOWN')
ax.set_xticks(ys);ax.set_xticklabels([str(y)+'s' for y in ys],rotation=58,ha='right',fontsize=8);ax.set_xlim(1784,2027);ax.grid(axis='y',alpha=.17);ax.set_axisbelow(True);ax.set_ylabel('Working document identities');ax.set_xlabel('Order issuance decade (not a complete all-history census)');ax.set_title('Executive orders: identified working bibliography and 2026 provisional legal statuses, Stage 17');ax.legend(loc='upper left',ncol=3)
ax.text(1798,max(map(sum,zip(no,yes,un)))*.65,'Early historical census seriously incomplete\n+5 newly catalogued 1789–1790 leads (not included)',fontsize=10,color='#6f4650',bbox={'facecolor':'#fff8ed','edgecolor':'none','alpha':.9})
fig.tight_layout();fig.savefig(r/'reports'/'ISSUANCE_DECADE_STATUS_STAGE17.png',dpi=175);plt.close(fig)
# A standalone HTML summary and source-based metrics, avoiding a false single all-work progress bar.
m=json.loads((r/'reports'/'METRICS_STAGE17.json').read_text())
html='''<!doctype html><html><head><meta charset="utf-8"><title>Stage17 evidence research dashboard</title><style>body{font:15px/1.45 system-ui;max-width:1080px;margin:30px auto;color:#152233}h1{font-size:24px}section{border-bottom:1px solid #ccd3dd;padding:15px 0}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(175px,1fr));gap:14px}.n{font-weight:bold;font-size:30px}small{color:#68717b}img{width:100%;max-width:1060px}</style></head><body><h1>Stage 17 · All-history EO research, 1789–2026</h1><p>Cutoff October 14, 2026. Research work metrics remain independent. Incomplete census and unverifiable original bytes are explicitly acknowledged.</p><section class="grid"><div><small>Identified working proxies</small><div class="n">14,972</div></div><div><small>Legacy v2 provisional classified</small><div class="n">3,055</div><small>20.4048% of working proxies</small></div><div><small>New scoped provision histories</small><div class="n">13</div></div><div><small>New scoped first-end hypotheses</small><div class="n">13</div></div><div><small>Human-certified reviews</small><div class="n">0</div></div></section><section><img src="ISSUANCE_DECADE_STATUS_STAGE17.png" alt="Stacked decadal histogram"/><p>Additional five 1789–1790 catalogue candidates excluded from the denominator. Undated 2026 proxy records are shown separately in CSV.</p></section><section><h2>Research capabilities</h2><p>540 Opus determinations imported with their AI review/source-original limitations; 531 held; 155 conflicts preserved. 438 Stage16 legal events plus 26 newly reasoned scoped transitions. 60,505 individual claims reviewable through the offline docket generator. Official text scans for most new studies are not stored locally.</p></section><section><h2>Validity constraints</h2><p>Historical national denominator unknown. Whole-order first cessation mostly unreconstructed. The 13 new provision-level first-end entries require human and source-image validation. A source's later formal revocation is not automatically a first cessation. Independent review and alternative TC06/TC07/TC09 semantics remain ongoing.</p></section></body></html>'''
(r/'reports'/'DASHBOARD_STAGE17.html').write_text(html)
print('dashboard generated, dated count',sum(sum(x.values()) for x in q.values()))
